using System;using System.IO;using System.Linq;using System.Security.Cryptography;using UnityEngine;using UnityEditor;
public static class AuditWreckageExport
{
 static int checks;static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}static string Hash(string p){using(var f=File.OpenRead(p))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(f)).Replace("-","");}
 public static object Run(){checks=0;string root=(System.Environment.GetEnvironmentVariable("GUNMAGGEDON_ROOT") ?? throw new System.InvalidOperationException("Set GUNMAGGEDON_ROOT before running editor tools or fixtures.")),path=root+"/ModBuild/0.0.41/Gunmageddon_0.0.41.nobp";var b=AssetBundle.LoadFromFile(path);if(!b)throw new Exception("Cannot load wreckage pack");try{var names=b.GetAllAssetNames();Check(!names.Any(n=>n.Contains("_donotship")||n.Contains("blueprintersetupbackups")||n.Contains("gunmaggedonstaging")||n.EndsWith(".dll")||n.EndsWith(".cs")),"No private dependencies or backups bundled");var shader=b.LoadAsset<Shader>("assets/blueprinter/mods/gunmageddon/wreckage/wreckscorch.shader");Check(shader&&shader.isSupported,"Compiled shared wreck shader is supported");var soot=b.LoadAsset<Texture2D>("assets/blueprinter/mods/gunmageddon/wreckage/shared_wreck_soot.asset");Check(soot&&soot.width==128&&soot.mipmapCount>1,"Shared mipmapped soot texture survives export");int wrecks=0,assigned=0,groups=0;foreach(string n in names.Where(n=>n.EndsWith(".prefab"))){var prefab=b.LoadAsset<GameObject>(n);if(!prefab)continue;var unit=prefab.GetComponent<Unit>();if(unit is Building||unit is GroundVehicle){var w=new SerializedObject(unit).FindProperty("wreckage").objectReferenceValue as GameObject;Check(w,"Every platform has wreck reference after export");if(w.name.EndsWith("_Wreck",StringComparison.Ordinal))assigned++;}foreach(var group in prefab.GetComponentsInChildren<LODGroup>(true)){groups++;var levels=group.GetLODs();var tris=levels.Select(l=>l.renderers.Sum(r=>{Check(r,"LOD renderer reference");var m=r.GetComponent<MeshFilter>().sharedMesh;long count=0;for(int i=0;i<m.subMeshCount;i++)count+=(long)m.GetIndexCount(i)/3;return count;})).ToArray();Check(group.enabled&&levels.Length>=3&&tris[0]>tris[1]&&tris[1]>tris[2],"Progressively cheaper exported LODs");}if(!n.Contains("/wreckage/")||!n.EndsWith("_wreck.prefab"))continue;wrecks++;Check(!unit&&!prefab.GetComponent<Mirage.NetworkIdentity>(),"Wreck cannot become an operational unit");Check(prefab.GetComponentsInChildren<MonoBehaviour>(true).All(c=>c is Wreckage),"No active weapon/controller scripts");foreach(var renderer in prefab.GetComponentsInChildren<MeshRenderer>(true))foreach(var material in renderer.sharedMaterials)Check(material&&material.shader==shader&&material.GetTexture("_SootMap")==soot,"Exported materials retain shared scorch shader/texture");}
  Check(wrecks==15&&assigned==15,"All15new wreck assignments survive export");Check(names.Count(n=>n.Contains("/wreckage/")&&b.LoadAsset<Texture2D>(n))==1,"No per-wreck texture sets");Check(names.Count(n=>b.LoadAsset<AudioClip>(n))==9,"Existing nine custom sounds unchanged");var manifest=b.LoadAsset<TextAsset>("assets/blueprinter/generated/patch_manifest.json");Check(manifest&&(string)Newtonsoft.Json.Linq.JObject.Parse(manifest.text)["modVersion"]=="0.0.41","Correct export version/remap manifest");var result=new{passed=true,checks,assets=names.Length,wrecks,assigned,groups,sharedSootTextures=1,pack="0.0.41",runtime="1.22.0",packSha256=Hash(path),runtimeSha256=Hash(root+"/GunmaggedonRuntime/build/1.22.0/Gunmaggedon.Runtime.dll")};string json=Newtonsoft.Json.JsonConvert.SerializeObject(result);File.WriteAllText(root+"/GunmaggedonRuntime/build/wreckage/export-audit.json",json);return json;}finally{b.Unload(true);}}
